arguments.cmd:
cat > /app/output/chart.mmd <<'EOF'
xychart-beta
    title "Top 15 Economies by GDP Rank (1970–2025)"
    x-axis "Year" [1970, 1980, 1990, 2000, 2010, 2025]
    y-axis "GDP Rank (1 = highest)" 1 --> 15
    line "United States" [1, 1, 1, 1, 1, 1]
    line "Japan" [3, 2, 2, 2, 3, 4]
    line "Germany" [2, 3, 3, 3, 4, 3]
    line "France" [4, 4, 4, 5, 5, 7]
    line "United Kingdom" [5, 5, 6, 4, 6, 6]
    line "Italy" [6, 6, 5, 6, 7, 9]
    line "Canada" [7, 7, 7, 7, 9, 10]
    line "China" [9, 10, 10, 6, 2, 2]
    line "Brazil" [8, 8, 9, 9, 8, 8]
    line "India" [13, 13, 13, 12, 10, 5]
    line "Australia" [10, 11, 11, 11, 13, 13]
    line "South Korea" [15, 15, 15, 13, 14, 12]
    line "Mexico" [12, 12, 12, 10, 11, 14]
    line "Spain" [11, 9, 8, 8, 12, 15]
    line "Russia" [14, 14, 14, 14, 15, 11]
EOF

cat > /app/output/chart.css <<'EOF'
:root {
  --base-line: #A7B1BC;
  --text: #1A1A1A;
}

svg {
  background: #FFFFFF;
  font-family: "Inter", "Segoe UI", Roboto, Arial, sans-serif;
}

/* Title */
svg .mainTitle {
  fill: var(--text) !important;
  font-size: 30px !important;
  font-weight: 700 !important;
}

/* Axis labels and ticks */
svg .xLabel,
svg .yLabel {
  fill: #2B2B2B !important;
  font-size: 18px !important;
  font-weight: 600 !important;
}

svg .label text,
svg .tick text,
svg .axisLabel {
  fill: #3A3A3A !important;
  font-size: 14px !important;
}

/* Grid and axis lines */
svg .tick line,
svg .domain,
svg .line-plot-0 .plot-line {
  stroke: #D6DCE3 !important;
}

/* Make all non-highlight country lines subdued */
svg .plot-line {
  stroke: var(--base-line) !important;
  stroke-width: 2 !important;
  opacity: 0.7 !important;
}

/* Highlight lines by series index (based on declaration order in .mmd) */
/* Japan = 2nd line */
svg .line-plot-1 .plot-line {
  stroke: #F28E2B !important;
  stroke-width: 5 !important;
  opacity: 1 !important;
}

/* China = 8th line */
svg .line-plot-7 .plot-line {
  stroke: #D7263D !important;
  stroke-width: 6 !important;
  opacity: 1 !important;
}

/* India = 10th line */
svg .line-plot-9 .plot-line {
  stroke: #2A9D8F !important;
  stroke-width: 5 !important;
  opacity: 1 !important;
}

/* Legend text */
svg .legend text {
  fill: #2B2B2B !important;
  font-size: 13px !important;
}
EOF

npx -y @mermaid-js/mermaid-cli -i /app/output/chart.mmd -o /app/output/result.png -t neutral -b white --scale 2 --width 1800 --height 1100 --cssFile /app/output/chart.css
file /app/output/result.png

